use std::collections::HashSet;
use std::ops::Range;

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Heading {
    pub level: u8,
    pub id: String,
    pub title: String,
    pub chars: u32,
}

#[derive(Debug)]
pub struct Page {
    body: String,
    draft: bool,
}

struct Span {
    heading: Heading,
    range: Range<usize>,
}

impl Page {
    pub fn parse(text: &str) -> Page {
        let result: Page = todo!("Page.parse");
        debug_assert!(text.ends_with(&result.body), "Page.parse: body is the text after the frontmatter");
        result
    }

    pub fn body(&self) -> &str {
        &self.body
    }

    pub fn is_draft(&self) -> bool {
        self.draft
    }

    pub fn toc(&self) -> Vec<Heading> {
        let result: Vec<Heading> = todo!("Page.toc");
        debug_assert!(ids_unique(&result), "Page.toc: ids are unique");
        debug_assert!(levels_valid(&result), "Page.toc: levels are 1 to 6");
        debug_assert!(chars_fit(&result, &self.body), "Page.toc: no section is longer than the body");
        result
    }

    pub fn section(&self, id: &str) -> Option<&str> {
        let result: Option<&str> = todo!("Page.section");
        debug_assert!(result.is_none_or(|s| is_slice_of(s, &self.body)), "Page.section: section is a slice of the body");
        result
    }

    fn spans(&self) -> Vec<Span> {
        let result: Vec<Span> = todo!("Page.spans");
        debug_assert!(result.iter().all(|s| s.range.end <= self.body.len()), "Page.spans: ranges inside the body");
        result
    }
}

pub(crate) fn heading_id(title: &str, seen: &HashSet<String>) -> String {
    let result: String = todo!("heading_id");
    debug_assert!(!seen.contains(&result), "heading_id: id not seen before");
    debug_assert!(!result.contains(char::is_whitespace), "heading_id: no whitespace");
    result
}

fn ids_unique(headings: &[Heading]) -> bool {
    let mut seen = HashSet::new();
    headings.iter().all(|h| seen.insert(h.id.as_str()))
}

fn levels_valid(headings: &[Heading]) -> bool {
    headings.iter().all(|h| (1..=6).contains(&h.level))
}

fn chars_fit(headings: &[Heading], body: &str) -> bool {
    let total = body.chars().count();
    headings.iter().all(|h| h.chars as usize <= total)
}

fn is_slice_of(part: &str, whole: &str) -> bool {
    let start = part.as_ptr() as usize;
    let base = whole.as_ptr() as usize;
    start >= base && start + part.len() <= base + whole.len()
}

